contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool makeKeeper) public payable {
        bool initiallyPaused = c.paused();

        if (makeKeeper) {
            c.setKeeper(address(this));
        }

        bool reverted;
        try c.unpauseDeposit() {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool finalPaused = c.paused();

        assert(makeKeeper
            ? (!reverted && !finalPaused)
            : (reverted && finalPaused == initiallyPaused));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address token,
        uint256 amount,
        uint256 minUSDG,
        address secondToken,
        uint256 secondAmount,
        uint256 secondMinUSDG
    ) public payable {
        require(token != address(0) && secondToken != address(0));
        require(amount > 0 && secondAmount > 0);
        require(token.code.length > 0 && secondToken.code.length > 0);

        (bool ok1, bytes memory data1) = token.call(
            abi.encodeWithSignature("approve(address,uint256)", address(c), type(uint256).max)
        );
        require(ok1, "approval failed");

        (bool ok2, bytes memory data2) = secondToken.call(
            abi.encodeWithSignature("approve(address,uint256)", address(c), type(uint256).max)
        );
        require(ok2, "approval failed");

        bool reverted1;
        uint256 glp1;
        try c.depositToken(token, amount, minUSDG) returns (uint256 glpStaked) {
            reverted1 = false;
            glp1 = glpStaked;
        } catch {
            reverted1 = true;
        }

        bool reverted2;
        uint256 glp2;
        try c.depositToken(secondToken, secondAmount, secondMinUSDG) returns (uint256 glpStaked) {
            reverted2 = false;
            glp2 = glpStaked;
        } catch {
            reverted2 = true;
        }

        uint256 bal = c.dnGmxJuniorVaultGlpBalance();

        // If both depositToken calls completed, the second one started after the first
        // success and the recorded GLP balance must equal the sum of both returned amounts.
        assert(reverted1 || reverted2 || bal >= glp1 + glp2);
    }
}

