    }

    function run(address caller) public {
        bool reverted;

        // Ensure there is at least one USDC-deposited round so executeBatchDeposit has work to do.
        // However, executeBatchDeposit can be called even without deposits; it will just return.
        // We focus on the access-control + cooldown rule.

