        address keeper = c.keeper();

        // Try to call executeBatchDeposit from a non-keeper (the test contract itself is the only caller we control).
        // We only run this branch if the test contract address is not the keeper.
        if (address(this) != keeper) {
            try c.executeBatchDeposit() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        } else {
            // The test contract is the keeper. The call should not revert if the cooldown has passed.
            // On a fresh deployment, lastUnpauseTimestamp is 0, so block.timestamp > 0 + 15 minutes must hold.
            // Since the test runs in a single transaction, block.timestamp is the same for all calls.
            // We cannot control block.timestamp, but on a real chain it will be > 15 minutes.
            // To make the test deterministic and still meet the requirement of a general rule,
            // we use a try/catch and assert that if it reverts, the revert is due to the cooldown.
            // However, we cannot inspect revert reason bytes reliably. So we assert that the call either succeeds
            // or the caller is not the keeper. But here the caller IS the keeper, so it must succeed.
            try c.executeBatchDeposit() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted);
        }
    }

    receive() external payable {}
}

