}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 seed) public {
        require(seed >= 0);

        bool reverted;
        bool value;
        try c.paused() returns (bool v) {
            reverted = false;
            value = v;
        } catch {
            reverted = true;
        }

        assert(reverted || value == value);
    }
}

