contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0, "amount must be positive");

        bool reverted;
        try c.executeBatchStake() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            bool isPaused = c.paused();
            assert(isPaused);
        } else {
            assert(true);
        }
    }
}

