contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 newThreshold) public payable {
        c.setThresholds(newThreshold);
        assert(c.slippageThresholdGmxBps() == newThreshold);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 newThreshold) public payable {
        uint256 before = c.slippageThresholdGmxBps();
        bool reverted;
        try c.setThresholds(newThreshold) { reverted = false; } catch { reverted = true; }
        uint256 after_ = c.slippageThresholdGmxBps();
        assert(reverted ? after_ == before : after_ == newThreshold);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 newThreshold) public payable {
        require(newThreshold <= type(uint256).max, "bound");
        uint256 before = c.slippageThresholdGmxBps();
        bool reverted;
        try c.setThresholds(newThreshold) { reverted = false; } catch { reverted = true; }
        uint256 after_ = c.slippageThresholdGmxBps();
        assert(reverted ? after_ == before : after_ == newThreshold);
    }
}
